        hist_idx_hist_enable = hist_idx_hist_enable + 1;
        seq_ok = 1'b1;
        seq_bad = 0;
        for (wi = 0; wi < 40; wi = wi + 1) begin
            if ((hist_value[hist_idx_hist_value - 40 + wi] - hist_value[hist_idx_hist_value - 40 - 1 + wi]) !== hist_enable[hist_idx_hist_enable - 40 - 1 + wi]) begin
                seq_ok = 1'b0;
