        end
        checks = checks + 1;
        if (!seq_ok) begin fails = fails + 1; $display("CHECK step_equals_enable#0 FAIL (seq_step top_value idx=%0d", seq_bad); end else $display("CHECK step_equals_enable#0 PASS");

